import Foundation

/// Real-dump RSA vectors for Phase-11 signature validation — generated from
/// three oracle whole-flash images (CSME12 = 2048-bit PKCS#1 v1.5 / SHA-256,
/// CSME15 & CSME16 = 3072-bit SSA-PSS / SHA-384). Reference validity confirmed
/// with a line-for-line Python mirror of `rsa_sig_val`.
enum RealManifests {
    /// Decode an even-length uppercase hex string.
    static func hex(_ s: String) -> Data {
        var out = Data()
        var i = s.startIndex
        while i < s.endIndex {
            let next = s.index(i, offsetBy: 2)
            out.append(UInt8(s[i..<next], radix: 16)!)
            i = next
        }
        return out
    }

    // CSME12
    static let CSME12Key = hex("")
    static let CSME12Sig = hex("")
    static let CSME12Protected = hex("")
    static let CSME12Exp: UInt32 = 65537

    // CSME15
    static let CSME15Key = hex("")
    static let CSME15Sig = hex("")
    static let CSME15Protected = hex("")
    static let CSME15Exp: UInt32 = 65537


    // CSME16 (from ~/Desktop/new.bin, whole flash, operational $MN2 @0x632CC,
    // 16.1.25.2020, R2 3072-bit). Same PSS scheme as CSME15 but a modulus whose
    // top limb is >= 0x80000000 — the case that exposed the Montgomery
    // 2n-vs-R top-limb truncation bug.
    static let CSME16Key = hex("")
    static let CSME16Sig = hex("")
    static let CSME16Protected = hex("")
    static let CSME16Exp: UInt32 = 65537

}
